<script setup lang="ts">
import {site} from './config/site'
const {pillars,products,reviews}=site
const nav=ref(false),exit=ref('#3a2418'),filter=ref('Todos'),enabled=useMotionPreference(),dialog=ref<HTMLDialogElement>(),selected=ref<(typeof products)[number]>()
const theme=computed(()=>Object.fromEntries([...Object.entries(site.colors).map(([k,v])=>[`--${k}`,v]),['--display',`${site.fonts.display},serif`],['--sans',`${site.fonts.body},sans-serif`]]))
const socialLinks=Object.entries(site.socials).filter(([,url])=>/^https:\/\//.test(url))
const mapDirections=`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(site.contacts.mapQuery)}`
const mapEmbed=`https://maps.google.com/maps?q=${encodeURIComponent(site.contacts.mapQuery)}&output=embed`
const shown=computed(()=>products.filter(p=>filter.value==='Todos'||p.category===filter.value))
const validWhatsApp=computed(()=>/^\d{10,15}$/.test(site.contacts.whatsapp))
const orderUrl=(name:string)=>`https://wa.me/${site.contacts.whatsapp}?text=${encodeURIComponent(`Olá! Gostaria de pedir ${name}.`)}`
const toggleMotion=()=>{enabled.value=!enabled.value;try{localStorage.setItem('refugio-motion',enabled.value?'on':'off')}catch{}}
const details=(product:(typeof products)[number])=>{selected.value=product;dialog.value?.showModal()}
const close=()=>dialog.value?.close()
useHead({link:[{rel:'icon',type:'image/svg+xml',href:'/favicon.svg'}],meta:[{property:'og:title',content:'O Refúgio — pão, café & tempo'},{property:'og:description',content:site.hero.description},{property:'og:image',content:'/images/Pao-1440.webp'}],script:[{type:'application/ld+json',innerHTML:JSON.stringify({'@context':'https://schema.org','@type':'Bakery',name:site.name,description:site.hero.description})}]})
</script>
<template>
<div :class="{'animations-off':!enabled}" :style="theme">
  <a class="skip" href="#essencia">Pular para o conteúdo</a>
  <header class="navbar" :class="{'nav-visible':nav}" :inert="!nav"><a class="brand" href="#inicio">{{site.logo}}</a><nav aria-label="Navegação principal"><a href="#cardapio">Cardápio</a><a href="#historia">Nossa história</a><a href="#visita">Visite-nos</a></nav></header>
  <main>
    <Hero @nav="nav=$event" @exit="exit=$event"/>
    <div class="transition-band" :style="{'--exit-color':exit}" aria-hidden="true"/>
    <ToneSection id="essencia" class="essence" tone="var(--cream)" next="var(--beige)"><div class="wrap">
      <UiBlurReveal><p class="eyebrow">Nossa essência</p></UiBlurReveal>
      <div class="essence-grid"><UiBlurReveal><h2>As melhores coisas<br>pedem uma pausa.</h2><p class="lead">O pão ainda morno. O café sem pressa.<br>Uma mesa onde você pode simplesmente ficar.</p><a class="text-link" href="#historia">Entre, a casa é sua <span>↗</span></a></UiBlurReveal><BreadPortrait/></div>
      <div class="pillars"><UiBlurReveal v-for="(p,i) in pillars" :key="p.title" :delay="i*.08"><h3>{{p.title}}</h3><p>{{p.copy}}</p></UiBlurReveal></div>
    </div></ToneSection>
    <Story/>
    <ToneSection id="cardapio" class="menu-section" tone="var(--cream)" next="var(--beige)"><div class="wrap"><div class="section-heading"><UiBlurReveal><p class="eyebrow">Nossos favoritos</p><h2>Feitos aqui.<br>Para o seu dia.</h2></UiBlurReveal><UiBlurReveal><p>Da primeira fornada ao último café,<br>sempre tem um bom motivo para voltar.</p></UiBlurReveal></div>
      <div class="filters" role="group" aria-label="Categorias do cardápio"><button v-for="category in ['Todos','Pães','Folhados','Cafés']" :key="category" :aria-pressed="filter===category" @click="filter=category">{{category}}</button></div>
      <div class="product-grid"><article v-for="(p,i) in shown" :key="p.name" class="product"><MotionImage :name="p.image" :alt="p.name" :variant="i%2?'float':'parallax'" :position="i>3?'right center':'center'"/><div class="product-heading"><h3>{{p.name}}</h3><UiNumberTicker :value="p.price"/></div><p>{{p.description}}</p><a v-if="validWhatsApp" class="text-link" :href="orderUrl(p.name)" target="_blank" rel="noopener noreferrer">Pedir <span>↗</span></a><button v-else class="text-link" @click="details(p)">Pedir <span>↗</span></button></article></div>
      <p class="demo-note">Cardápio e preços de demonstração. As cinco fotografias foram reutilizadas com enquadramentos diferentes.</p>
    </div></ToneSection>
    <ToneSection id="historia" class="history-section" tone="var(--beige)" next="var(--cream)"><div class="wrap history-grid"><div class="history-image"><MotionImage name="Pao_1" alt="Vitrine iluminada com croissants e plaquinhas de identificação" variant="morphMask"/></div><div><UiBlurReveal><p class="eyebrow">Nossa história</p><h2>Um lugar para<br>chamar de nosso.</h2></UiBlurReveal><UiBlurReveal><p>A ideia era simples: abrir uma porta, acender o forno e receber bem. O Refúgio nasceu dessa vontade de transformar o cotidiano em um lugar mais gostoso de estar.</p><p>Uma história ilustrativa de marca, feita para você adaptar à sua padaria.</p><ol class="timeline"><li><strong>A primeira receita</strong><span>O cuidado começa na escolha dos ingredientes.</span></li><li><strong>A primeira fornada</strong><span>Um jeito próprio de fazer, respeitando cada etapa.</span></li><li><strong>A próxima visita</strong><span>A melhor parte é ver a mesa se encher de novo.</span></li></ol><p class="signature">Da nossa casa, para a sua.</p></UiBlurReveal></div></div></ToneSection>
    <section id="experiencia" class="experience"><MotionImage name="Interior_de_uma_Padaria" alt="Interior da padaria com balcão e vitrine" variant="kenburns"/><div class="experience-shade"/><div class="experience-copy wrap"><UiBlurReveal><p class="eyebrow">Nossa experiência</p><h2>O seu lugar<br>entre uma coisa<br>e outra.</h2><p>Passe para um café. Fique para a conversa.<br>A gente cuida do resto.</p></UiBlurReveal></div></section>
    <div class="experience-join" aria-hidden="true"/>
    <ToneSection class="review-section" tone="var(--cream)" next="var(--beige)"><div class="wrap"><div class="section-heading"><UiBlurReveal><p class="eyebrow">Quem chega, fica</p><h2>Boas histórias<br>à nossa mesa.</h2></UiBlurReveal><p class="review-label">Avaliações de demonstração</p></div><div class="reviews"><UiBlurReveal v-for="r in reviews" :key="r.name"><blockquote><span class="quote-mark" aria-hidden="true">“</span><p>{{r.quote}}</p><cite>{{r.name}}</cite></blockquote></UiBlurReveal></div></div></ToneSection>
    <ToneSection id="visita" class="visit" tone="var(--beige)" next="var(--cream)"><div class="wrap"><div class="visit-grid"><UiBlurReveal><p class="eyebrow">Visite-nos</p><h2>Tem um lugar<br>esperando por você.</h2><p>Da primeira xícara à última fornada.<br>Vai ser bom ter você por aqui.</p><dl><div v-for="hour in site.hours" :key="hour.days"><dt>{{hour.days}}</dt><dd>{{hour.time}}</dd></div></dl><p>{{site.contacts.demonstration ? "Localização de demonstração:" : "Nosso endereço:"}}<br>{{site.contacts.address}}</p><a class="button coffee-button" :href="mapDirections" target="_blank" rel="noopener noreferrer">Como chegar <span>↗</span></a></UiBlurReveal><div class="visit-image"><MotionImage name="Croassaint_com_Cafe" alt="Croissant e café servidos na mesa" variant="float"/><span class="visit-seal">Pode chegar.<br>A casa é sua.</span></div></div><details class="map-panel"><summary>Ver localização de demonstração no mapa</summary><iframe :src="mapEmbed" title="Mapa da localização demonstrativa em São Paulo" loading="lazy" referrerpolicy="no-referrer" sandbox="allow-scripts allow-same-origin allow-popups"/></details></div></ToneSection>
    <section class="last-call"><div class="wrap"><UiBlurReveal><p class="eyebrow">Pão, café e tempo.</p><h2>Seu próximo bom<br>momento começa aqui.</h2><UiShimmerButton href="#cardapio">Escolha seu favorito <span>↗</span></UiShimmerButton></UiBlurReveal></div></section>
    <UiMarquee><span>feito à mão</span><span aria-hidden="true">✳</span><span>servido com calma</span><span aria-hidden="true">✳</span><span>feito com carinho</span><span aria-hidden="true">✳</span></UiMarquee>
  </main>
  <footer class="site-footer"><div class="wrap"><div class="footer-top"><a class="footer-brand" href="#inicio">{{site.logo}}</a><p>Pães fresquinhos.<br>Memórias quentinhas.</p></div><div class="footer-links"><nav aria-label="Navegação do rodapé"><a href="#cardapio">Cardápio</a><a href="#historia">Nossa história</a><a href="#visita">Visite-nos</a></nav><button :aria-pressed="enabled" @click="toggleMotion">Animações: {{enabled?'ativadas':'reduzidas'}}</button></div><nav v-if="socialLinks.length" class="social-links" aria-label="Redes sociais"><a v-for="[name,url] in socialLinks" :key="name" :href="url" target="_blank" rel="noopener noreferrer">{{name}}</a></nav><p class="footer-note">© {{new Date().getFullYear()}} O Refúgio. Template demonstrativo: textos, produtos, avaliações, horários e endereço são ilustrativos. Fotografias fornecidas para este projeto.</p></div></footer>
  <a v-if="validWhatsApp" class="whatsapp" :href="orderUrl('informações')" target="_blank" rel="noopener noreferrer" aria-label="Falar com a padaria pelo WhatsApp">WhatsApp</a>
  <dialog ref="dialog" class="product-dialog" @click="($event.target===dialog)&&close()"><div v-if="selected"><button class="dialog-close" aria-label="Fechar" @click="close">×</button><p>Produto de demonstração</p><h2>{{selected.name}}</h2><p>{{selected.description}}</p><p>{{new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(selected.price)}}</p><p>O contato desta padaria ainda não foi informado. Nenhum pedido será enviado por esta demonstração.</p><button class="button coffee-button" @click="close">Continuar no cardápio</button></div></dialog>
  <noscript><style>.reveal{opacity:1!important;transform:none!important}.navbar{display:none}</style></noscript>
</div>
</template>
